    fn start_plugin_registry_operation(&mut self, operation: PluginRegistryOperation) {
        if self.extensions_busy {
            return;
        }
        self.extensions_busy = true;
        self.extensions_error = None;
        self.extensions_operation_sequence = self.extensions_operation_sequence.saturating_add(1);
        let operation_id = self.extensions_operation_sequence;
        self.active_extensions_operation = Some(operation_id);
        let application = self.application.clone();
        let message_sender = Arc::clone(&self.message_sender);
        let spawn = std::thread::Builder::new()
            .name("lilia-plugins-registry".to_owned())
            .spawn(move || {
                let result = match operation {
                    PluginRegistryOperation::Install(input) => {
                        application.install_plugin_package(input).map(|_| ())
                    }
                    PluginRegistryOperation::SetEnabled {
                        plugin_id,
                        enabled,
                        expected_registry_revision,
                    } => application
                        .set_plugin_package_enabled(&plugin_id, enabled, expected_registry_revision)
                        .map(|_| ()),
                    PluginRegistryOperation::Delete {
                        plugin_id,
                        expected_registry_revision,
                    } => application.delete_plugin_package(&plugin_id, expected_registry_revision),
                }
                .and_then(|_| application.extensions_snapshot())
                .map_err(|error| error.to_string());
                let _ = message_sender(Message::PluginOperationFinished {
                    operation_id,
                    result,
                });
            });
        if let Err(error) = spawn {
            eprintln!("failed to start Native Preview Plugin registry operation: {error}");
            self.active_extensions_operation = None;
            self.extensions_busy = false;
            self.extensions_error = Some("无法更新 Plugins 注册表，请稍后重试。".to_owned());
        }
    }

    fn create_hook_source(&mut self, source_id: &str) {
        let Some(source) = self.hook_source_by_id(source_id) else {
            return;
        };
        if source.exists {
            return;
        }
        self.start_hook_source_operation(HookSourceOperation::Create {
            scope: source.scope,
            project_cwd: source.project_cwd,
        });
    }

    fn update_hook_handler_draft(
        &mut self,
        source_id: &str,
        index: usize,
        field: HookHandlerDraftField,
        value: String,
    ) {
        if self.extensions_busy {
            return;
        }
        let draft = self
            .hook_drafts
            .get(source_id)
            .cloned()
            .unwrap_or_else(|| hook_handlers_draft(&[]));
        match edit_hook_handler_draft(&draft, index, field, value) {
            Ok(draft) => {
                self.hook_drafts.insert(source_id.to_owned(), draft);
                self.extensions_error = None;
            }
            Err(error) => self.extensions_error = Some(error),
        }
    }

    fn add_hook_handler_draft(&mut self, source_id: &str) {
        if self.extensions_busy {
            return;
        }
        let draft = self
            .hook_drafts
            .get(source_id)
            .cloned()
            .unwrap_or_else(|| hook_handlers_draft(&[]));
        match add_hook_handler_to_draft(&draft) {
            Ok(draft) => {
                self.hook_drafts.insert(source_id.to_owned(), draft);
                self.extensions_error = None;
            }
            Err(error) => self.extensions_error = Some(error),
        }
    }

    fn remove_hook_handler_draft(&mut self, source_id: &str, index: usize) {
        if self.extensions_busy {
            return;
        }
        let Some(draft) = self.hook_drafts.get(source_id).cloned() else {
            return;
        };
        match remove_hook_handler_from_draft(&draft, index) {
            Ok(draft) => {
                self.hook_drafts.insert(source_id.to_owned(), draft);
                self.extensions_error = None;
            }
            Err(error) => self.extensions_error = Some(error),
        }
    }

    fn save_hook_source(&mut self, source_id: &str) {
        let Some(source) = self.hook_source_by_id(source_id) else {
            return;
        };
        if !source.exists {
            return;
        }
        let draft = self
            .hook_drafts
            .get(source_id)
            .map(String::as_str)
            .unwrap_or("[]");
        let handlers = match validated_hook_handlers(draft) {
            Ok(handlers) => handlers,
            Err(error) => {
                self.extensions_error = Some(error);
                return;
            }
        };
        self.start_hook_source_operation(HookSourceOperation::Update {
            scope: source.scope,
            project_cwd: source.project_cwd,
            input: DesktopHookDocumentUpdate {
                expected_revision: source.revision,
                handlers,
            },
        });
    }

    fn toggle_hook_source(&mut self, source_id: &str) {
        let Some(source) = self.hook_source_by_id(source_id) else {
            return;
        };
        if !source.exists {
            return;
        }
        self.start_hook_source_operation(HookSourceOperation::SetEnabled {
            scope: source.scope,
            project_cwd: source.project_cwd,
            expected_revision: source.revision,
            enabled: !source.enabled,
        });
    }

    fn confirm_delete_hook_source(&mut self) {
        let Some(source_id) = self.hook_delete_confirmation.clone() else {
            return;
        };
        let Some(source) = self.hook_source_by_id(&source_id) else {
            return;
        };
        if !source.exists {
            return;
        }
        self.start_hook_source_operation(HookSourceOperation::Delete {
            scope: source.scope,
            project_cwd: source.project_cwd,
            expected_revision: source.revision,
        });
    }

    fn hook_source_by_id(&self, source_id: &str) -> Option<DesktopHookSourceView> {
        self.hooks
            .as_ref()?
            .sources
            .iter()
            .find(|source| source.id == source_id)
            .cloned()
    }

    fn start_hook_source_operation(&mut self, operation: HookSourceOperation) {
        if self.extensions_busy {
            return;
        }
        self.extensions_busy = true;
        self.extensions_error = None;
        self.extensions_operation_sequence = self.extensions_operation_sequence.saturating_add(1);
        let operation_id = self.extensions_operation_sequence;
        self.active_extensions_operation = Some(operation_id);
        let overview_project_cwd = self.selected_project_workspace().map(|(_, root)| root);
        let application = self.application.clone();
        let message_sender = Arc::clone(&self.message_sender);
        let spawn = std::thread::Builder::new()
            .name("lilia-hooks-registry".to_owned())
            .spawn(move || {
                let operation_result = match operation {
                    HookSourceOperation::Create { scope, project_cwd } => application
                        .create_hook_source(scope, project_cwd.as_deref())
                        .map(|_| ()),
                    HookSourceOperation::Update {
                        scope,
                        project_cwd,
                        input,
                    } => application
                        .update_hook_source(scope, project_cwd.as_deref(), input)
                        .map(|_| ()),
                    HookSourceOperation::SetEnabled {
                        scope,
                        project_cwd,
                        expected_revision,
                        enabled,
                    } => application
                        .set_hook_source_enabled(
                            scope,
                            project_cwd.as_deref(),
                            expected_revision,
                            enabled,
                        )
                        .map(|_| ()),
                    HookSourceOperation::Delete {
                        scope,
                        project_cwd,
                        expected_revision,
                    } => application.delete_hook_source(
                        scope,
                        project_cwd.as_deref(),
                        expected_revision,
                    ),
                };
                let result = operation_result
                    .map_err(|error| error.to_string())
                    .and_then(|_| load_native_hooks(&application, overview_project_cwd.as_deref()));
                let _ = message_sender(Message::HookOperationFinished {
                    operation_id,
                    result,
                });
            });
        if let Err(error) = spawn {
            eprintln!("failed to start Native Preview Hook operation: {error}");
            self.active_extensions_operation = None;
            self.extensions_busy = false;
            self.extensions_error = Some("无法更新 Hooks，请稍后重试。".to_owned());
        }
    }

    fn apply_hooks_snapshot(&mut self, snapshot: NativeHooksSnapshot) {
        self.hook_drafts = snapshot
            .documents
            .iter()
            .map(|(source_id, document)| (source_id.clone(), hook_document_draft(document)))
            .collect();
        self.hook_documents = snapshot.documents;
        self.hooks = Some(snapshot.overview);
    }

