fn ordered_task_tree_indices(tasks: &[DesktopWorkspaceTask]) -> Vec<(usize, usize)> {
    fn append_subtree(
        root: usize,
        tasks: &[DesktopWorkspaceTask],
        visited: &mut BTreeSet<usize>,
        output: &mut Vec<(usize, usize)>,
    ) {
        let mut stack = vec![(root, 0_usize)];
        while let Some((index, depth)) = stack.pop() {
            if !visited.insert(index) {
                continue;
            }
            output.push((index, depth));
            let parent_id = &tasks[index].id;
            let children = tasks
                .iter()
                .enumerate()
                .filter(|(_, task)| task.parent_id.as_ref() == Some(parent_id))
                .map(|(child, _)| child)
                .collect::<Vec<_>>();
            for child in children.into_iter().rev() {
                stack.push((child, depth.saturating_add(1)));
            }
        }
    }

    let known_ids = tasks
        .iter()
        .map(|task| task.id.clone())
        .collect::<BTreeSet<_>>();
    let roots = tasks
        .iter()
        .enumerate()
        .filter(|(_, task)| {
            task.parent_id
                .as_ref()
                .is_none_or(|parent_id| parent_id == &task.id || !known_ids.contains(parent_id))
        })
        .map(|(index, _)| index)
        .collect::<Vec<_>>();
    let mut visited = BTreeSet::new();
    let mut output = Vec::with_capacity(tasks.len());
    for root in roots {
        append_subtree(root, tasks, &mut visited, &mut output);
    }
    for index in 0..tasks.len() {
        append_subtree(index, tasks, &mut visited, &mut output);
    }
    output
}

fn task_is_descendant_of(
    tasks: &[DesktopWorkspaceTask],
    candidate_id: &TaskId,
    ancestor_id: &TaskId,
) -> bool {
    let mut cursor = Some(candidate_id.clone());
    let mut visited = BTreeSet::new();
    while let Some(task_id) = cursor {
        if &task_id == ancestor_id {
            return true;
        }
        if !visited.insert(task_id.clone()) {
            return false;
        }
        cursor = tasks
            .iter()
            .find(|task| task.id == task_id)
            .and_then(|task| task.parent_id.clone());
    }
    false
}

fn product_task_is_descendant_of(
    tasks: &[ProductTask],
    candidate_id: &TaskId,
    ancestor_id: &TaskId,
) -> bool {
    let mut cursor = Some(candidate_id.clone());
    let mut visited = BTreeSet::new();
    while let Some(task_id) = cursor {
        if &task_id == ancestor_id {
            return true;
        }
        if !visited.insert(task_id.clone()) {
            return false;
        }
        cursor = tasks
            .iter()
            .find(|task| task.id == task_id)
            .and_then(|task| task.parent_id.clone());
    }
    false
}

fn session_search_hit_ids(application: &DesktopApplication, search: &str) -> BTreeSet<TaskId> {
    let query = search.trim();
    if query.is_empty() {
        return BTreeSet::new();
    }
    application
        .search_sessions(query, 100)
        .ok()
        .map(|results| results.into_iter().map(|result| result.task_id).collect())
        .unwrap_or_default()
}

fn task_matches_search(
    task: &DesktopWorkspaceTask,
    search: &str,
    session_hits: &BTreeSet<TaskId>,
) -> bool {
    let query = search.trim();
    if query.is_empty() {
        return true;
    }
    let lower = query.to_ascii_lowercase();
    if task.title.to_ascii_lowercase().contains(&lower)
        || task.id.as_str().to_ascii_lowercase().contains(&lower)
    {
        return true;
    }
    session_hits.contains(&task.id)
}

fn next_task_status(status: ProductTaskStatus) -> ProductTaskStatus {
    match status {
        ProductTaskStatus::Draft => ProductTaskStatus::Waiting,
        ProductTaskStatus::Waiting => ProductTaskStatus::Running,
        ProductTaskStatus::Running => ProductTaskStatus::Blocked,
        ProductTaskStatus::Blocked => ProductTaskStatus::Done,
        ProductTaskStatus::Done => ProductTaskStatus::Cancelled,
        ProductTaskStatus::Cancelled => ProductTaskStatus::Draft,
    }
}

