fn remove_abandoned_iab_snapshot(path: &std::path::Path) {
    if let Err(error) = std::fs::remove_file(path) {
        if error.kind() != std::io::ErrorKind::NotFound {
            eprintln!("failed to remove abandoned Native IAB snapshot: {error}");
        }
    }
}

