#[cfg(any(debug_assertions, test))]
fn parse_automation_scope_target(target_id: &str) -> Option<(&str, &str)> {
    const PREFIX: &str = "native-preview.automations.scope.";
    let suffix = target_id.strip_prefix(PREFIX)?;
    for field in ["project", "task-status", "backend", "event-kind"] {
        let Some(rest) = suffix.strip_prefix(field) else {
            continue;
        };
        if let Some(value) = rest.strip_prefix('.').filter(|value| !value.is_empty()) {
            return Some((field, value));
        }
    }
    None
}

