    fn workspace_task(id: &str, parent_id: Option<&str>) -> DesktopWorkspaceTask {
        DesktopWorkspaceTask {
            id: TaskId::new(id).unwrap(),
            title: id.to_owned(),
            parent_id: parent_id.map(|parent_id| TaskId::new(parent_id).unwrap()),
            status: ProductTaskStatus::Draft,
            priority: ProductTaskPriority::Normal,
            pinned: false,
            sort_order: 0,
        }
    }

    fn product_task(id: &str, parent_id: Option<&str>) -> ProductTask {
        let mut task = ProductTask::new(TaskId::new(id).unwrap(), None, id).unwrap();
        task.parent_id = parent_id.map(|parent_id| TaskId::new(parent_id).unwrap());
        task
    }

    #[test]
    fn task_tree_orders_parents_before_children_and_bounds_corrupt_cycles() {
        let tasks = vec![
            workspace_task("child", Some("parent")),
            workspace_task("parent", None),
            workspace_task("cycle-a", Some("cycle-b")),
            workspace_task("cycle-b", Some("cycle-a")),
            workspace_task("missing-parent", Some("missing")),
        ];
        let ordered = ordered_task_tree_indices(&tasks)
            .into_iter()
            .map(|(index, depth)| (tasks[index].id.as_str().to_owned(), depth))
            .collect::<Vec<_>>();
        assert_eq!(ordered[0], ("parent".to_owned(), 0));
        assert_eq!(ordered[1], ("child".to_owned(), 1));
        assert_eq!(ordered[2], ("missing-parent".to_owned(), 0));
        assert_eq!(ordered.len(), tasks.len());
        assert!(task_is_descendant_of(
            &tasks,
            &TaskId::new("child").unwrap(),
            &TaskId::new("parent").unwrap()
        ));
        assert!(!task_is_descendant_of(
            &tasks,
            &TaskId::new("parent").unwrap(),
            &TaskId::new("child").unwrap()
        ));
    }

    #[test]
    fn task_drop_parent_filter_rejects_descendants_and_bounds_corrupt_cycles() {
        let tasks = vec![
            product_task("root", None),
            product_task("child", Some("root")),
            product_task("grandchild", Some("child")),
            product_task("cycle-a", Some("cycle-b")),
            product_task("cycle-b", Some("cycle-a")),
        ];

        assert!(product_task_is_descendant_of(
            &tasks,
            &TaskId::new("grandchild").unwrap(),
            &TaskId::new("root").unwrap(),
        ));
        assert!(!product_task_is_descendant_of(
            &tasks,
            &TaskId::new("root").unwrap(),
            &TaskId::new("grandchild").unwrap(),
        ));
        assert!(!product_task_is_descendant_of(
            &tasks,
            &TaskId::new("cycle-a").unwrap(),
            &TaskId::new("root").unwrap(),
        ));
    }

    #[test]
    fn nana_pane_tree_preserves_workspace_identity_axis_and_ratio() {
        let mut layout = PanelLayoutSnapshot::default();
        let primary = PaneId::new("primary").unwrap();
        let secondary = PaneId::new("secondary").unwrap();
        layout
            .split_pane(&primary, secondary.clone(), SplitAxis::Vertical, 0.25)
            .unwrap();

        let tree = nana_pane_tree_node(&layout.panes);
        let mut panes = Vec::new();
        tree.visit_leaves(|pane_id| panes.push(pane_id.clone()));
        assert_eq!(panes, vec![primary.clone(), secondary.clone()]);
        let mut splits = Vec::new();
        tree.visit_splits(|key, axis, ratio| splits.push((key.clone(), axis, ratio)));
        assert_eq!(splits.len(), 1);
        assert_eq!(splits[0].0.first_pane_id, primary);
        assert_eq!(splits[0].0.second_pane_id, secondary);
        assert_eq!(splits[0].1, NanaSplitAxis::Vertical);
        assert_eq!(splits[0].2, 0.25);
    }

    #[test]
    fn project_reorder_contract_uses_before_value_and_rejects_foreign_targets() {
        let values = vec!["a", "b", "c"];
        assert_eq!(
            reordered_before(&values, &"c", Some(&"a")),
            Some(vec!["c", "a", "b"])
        );
        assert_eq!(
            reordered_before(&values, &"a", None),
            Some(vec!["b", "c", "a"])
        );
        assert_eq!(reordered_before(&values, &"a", Some(&"b")), None);
        assert_eq!(reordered_before(&values, &"a", Some(&"foreign")), None);
    }

    #[test]
    fn workspace_split_specs_follow_nested_ratio_geometry() {
        let mut layout = PanelLayoutSnapshot::default();
        let primary = PaneId::new("primary").unwrap();
        let secondary = PaneId::new("secondary").unwrap();
        let nested = PaneId::new("nested").unwrap();
        layout
            .split_pane(&primary, secondary.clone(), SplitAxis::Horizontal, 0.5)
            .unwrap();
        layout
            .split_pane(&primary, nested.clone(), SplitAxis::Vertical, 0.25)
            .unwrap();
        let mut specs = Vec::new();
        collect_workspace_split_specs(&layout.panes, 1_000.0, 800.0, &mut specs);

        assert_eq!(specs.len(), 2);
        assert_eq!(
            specs[0].key,
            WorkspaceSplitKey {
                first_pane_id: primary.clone(),
                second_pane_id: secondary,
            }
        );
        assert_eq!((specs[0].ratio, specs[0].extent), (0.5, 1_000.0));
        assert_eq!(
            specs[1].key,
            WorkspaceSplitKey {
                first_pane_id: primary,
                second_pane_id: nested,
            }
        );
        assert_eq!((specs[1].ratio, specs[1].extent), (0.25, 800.0));
    }

