    #[test]
    fn roadmap_dates_round_trip_and_reject_invalid_calendar_values() {
        let update = parse_civil_date_update("2028-02-29").unwrap();
        let MilestoneDueDateUpdate::Set(timestamp) = update else {
            panic!("expected a due date");
        };
        assert_eq!(format_civil_date(timestamp), "2028-02-29");
        assert!(parse_civil_date_update("2027-02-29").is_err());
        assert_eq!(
            parse_civil_date_update("  ").unwrap(),
            MilestoneDueDateUpdate::Clear
        );
    }

